/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: Entry, Messages
 *   Functions: entry, canonical, sortedRecord, writeSources, temporaryRoot, publicBytes
 *   Constants: runtimeCatalog, runtimeMessages, scopedKey, scopedEntry, scopedMessages
 * Tests
 *   - web-admin delivery adds scoped locale artifacts without changing v1 or v2 bytes and revisions
 *   - scoped messages require the same complete locale keys, plain ICU and named-variable contracts
 *   - larger authoring catalogs cannot expand runtime, legacy or scoped delivery limits
 *   - checking rejects missing and stale scoped artifacts and generation cleans all delivery groups
 * @end-catalog */

import assert from 'node:assert/strict';
import { mkdtemp, mkdir, readFile, rm, stat, unlink, writeFile } from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import test, { type TestContext } from 'node:test';

import { buildLocalizationArtifacts, checkLocalizationArtifacts, writeLocalizationArtifacts } from '../../scripts/build-localizations.mjs';

interface Entry { description: string; delivery: string[]; variables: Record<string, string> }
type Messages = Record<string, string>;
const entry = (delivery: string[], variables: Record<string, string> = {}): Entry => ({ description: 'Fixture', delivery, variables });
const runtimeCatalog = { 'admin.existing': entry(['runtime']), 'shell.home': entry(['runtime']) };
const runtimeMessages = { 'admin.existing': 'Existing administrator copy', 'shell.home': 'Home' };
const scopedKey = 'admin.pages.item_count';
const scopedEntry = entry(['web-admin'], { count: 'number' });
const scopedMessages = { ...runtimeMessages, [scopedKey]: '{count, plural, one {# item} other {# items}}' };
const canonical = (value: unknown) => JSON.stringify(value, null, 2) + '\n';
const sortedRecord = <T>(value: Record<string, T>) => Object.fromEntries(Object.entries(value).sort(([a], [b]) => a.localeCompare(b)));

/** Writes complete canonical authoring sources, independent of any checked-in translation artifacts. */
async function writeSources(root: string, catalog: Record<string, Entry>, en: Messages, zh: Messages = en) {
  const directory = path.join(root, 'localization');
  await mkdir(path.join(directory, 'locales'), { recursive: true });
  await writeFile(path.join(directory, 'catalog.json'), canonical({ schemaVersion: 1, locales: {
    'en-US': { nativeName: 'English (United States)', englishName: 'English (United States)' },
    'zh-Hans': { nativeName: '简体中文', englishName: 'Simplified Chinese' }
  }, messages: sortedRecord(catalog) }));
  await writeFile(path.join(directory, 'locales/en-US.json'), canonical(sortedRecord(en)));
  await writeFile(path.join(directory, 'locales/zh-Hans.json'), canonical(sortedRecord(zh)));
}

/** Each test owns its generated files and removes them without touching repository or native resources. */
async function temporaryRoot(t: TestContext) {
  const root = await mkdtemp(path.join(os.tmpdir(), 'archtree-web-admin-localizations-'));
  t.after(() => rm(root, { recursive: true, force: true }));
  return root;
}

/** Captures the existing public delivery representations exactly as a client downloads them. */
async function publicBytes(root: string) {
  const files = ['manifest.json', 'bundles/en-US.json', 'bundles/zh-Hans.json'];
  return Promise.all(['', 'legacy'].flatMap(group => files.map(file =>
    readFile(path.join(root, 'localization/generated', group, file), 'utf8'))));
}

test('web-admin delivery adds scoped locale artifacts without changing v1 or v2 bytes and revisions', async t => {
  const root = await temporaryRoot(t);
  await writeSources(root, runtimeCatalog, runtimeMessages);
  const before = await writeLocalizationArtifacts(root);
  const bytes = await publicBytes(root);
  assert.equal(before.webAdmin, undefined);
  await assert.rejects(stat(path.join(root, 'localization/generated/web-admin')), { code: 'ENOENT' });

  const zh = { ...runtimeMessages, [scopedKey]: '{count} 个项目' };
  await writeSources(root, { ...runtimeCatalog, [scopedKey]: scopedEntry }, scopedMessages, zh);
  const after = await writeLocalizationArtifacts(root);
  assert.deepEqual(after.manifest, before.manifest);
  assert.deepEqual(after.bundles, before.bundles);
  assert.deepEqual(after.legacy, before.legacy);
  assert.deepEqual(await publicBytes(root), bytes);
  assert.equal(after.webAdmin.bundles.size, 2);
  assert.deepEqual(after.webAdmin.bundles.get('zh-Hans').messages, { [scopedKey]: '{count} 个项目' });
  assert.deepEqual(after.webAdmin.manifest.locales.map(({ locale }: { locale: string }) => locale), ['en-US', 'zh-Hans']);
  const packaged = JSON.parse(await readFile(path.join(root, 'localization/generated/web-admin/bundles/en-US.json'), 'utf8'));
  assert.equal(packaged.schemaVersion, 1);
  assert.equal(packaged.locale, 'en-US');
  assert.deepEqual(packaged.messages, { [scopedKey]: scopedMessages[scopedKey] });
  assert.equal(after.bundles.get('en-US').messages[scopedKey], undefined);
  assert.equal(after.legacy.bundles.get('en-US').messages[scopedKey], undefined);
  await checkLocalizationArtifacts(root);
});

test('scoped messages require the same complete locale keys, plain ICU and named-variable contracts', async t => {
  const root = await temporaryRoot(t);
  const catalog = { ...runtimeCatalog, [scopedKey]: scopedEntry };
  for (const [label, message, error] of [
    ['missing variable', 'Items', /named-variable set/],
    ['wrong formatter type', '{count, date}', /formats count as date, not number/],
    ['malformed ICU', '{count, plural, one {# item}', /invalid ICU MessageFormat/],
    ['rich text', '<b>{count}</b>', /plain text rather than rich-text tags/]
  ] as const) {
    await t.test(label, async () => {
      await writeSources(root, catalog, scopedMessages, { ...runtimeMessages, [scopedKey]: message });
      await assert.rejects(buildLocalizationArtifacts(root), error);
    });
  }
  await writeSources(root, catalog, scopedMessages, runtimeMessages);
  await assert.rejects(buildLocalizationArtifacts(root), /exactly the catalog message-key set/);
  await writeSources(root, { ...runtimeCatalog, 'shell.private': entry(['web-admin']) }, { ...runtimeMessages, 'shell.private': 'Invalid scope' });
  await assert.rejects(buildLocalizationArtifacts(root), /admin namespace for web-admin delivery/);
});

test('larger authoring catalogs cannot expand runtime, legacy or scoped delivery limits', async t => {
  const root = await temporaryRoot(t);
  const catalog: Record<string, Entry> = { 'shell.home': entry(['runtime']), [scopedKey]: entry(['web-admin']) };
  const messages: Messages = { 'shell.home': 'Home', [scopedKey]: 'Scoped administrator copy' };
  for (let index = 0; index < 1_999; index++) {
    const key = 'admin.existing_' + String(index).padStart(4, '0');
    catalog[key] = entry(['runtime']); messages[key] = 'Existing copy';
  }
  await writeSources(root, catalog, messages);
  const atLimit = await buildLocalizationArtifacts(root);
  assert.equal(atLimit.bundles.get('en-US').messages['shell.home'], 'Home');
  assert.equal(Object.keys(atLimit.bundles.get('en-US').messages).length, 2_000);
  assert.equal(Object.keys(atLimit.webAdmin.bundles.get('en-US').messages).length, 1);

  await writeSources(root, { ...catalog, 'admin.overflow': entry(['runtime']) }, { ...messages, 'admin.overflow': 'Over limit' });
  await assert.rejects(buildLocalizationArtifacts(root), /v2 runtime localization namespace must contain 1–2000 messages/);
  const legacyCatalog: Record<string, Entry> = {}, legacyMessages: Messages = {};
  for (let index = 0; index < 1_001; index++) {
    const key = 'shell.copy_' + String(index).padStart(4, '0');
    legacyCatalog[key] = entry(['runtime']); legacyMessages[key] = 'Listener copy';
  }
  await writeSources(root, legacyCatalog, legacyMessages);
  await assert.rejects(buildLocalizationArtifacts(root), /v1 listener localization namespace must contain 1–1000 messages/);

  const scopedCatalog: Record<string, Entry> = { 'shell.home': entry(['runtime']) }, scoped: Messages = { 'shell.home': 'Home' };
  for (let index = 0; index < 2_001; index++) {
    const key = 'admin.pages.copy_' + String(index).padStart(4, '0');
    scopedCatalog[key] = entry(['web-admin']); scoped[key] = 'Scoped copy';
  }
  await writeSources(root, scopedCatalog, scoped);
  await assert.rejects(buildLocalizationArtifacts(root), /web-admin localization namespace must contain 1–2000 messages/);
});

test('checking rejects missing and stale scoped artifacts and generation cleans all delivery groups', async t => {
  const root = await temporaryRoot(t);
  await writeSources(root, { ...runtimeCatalog, [scopedKey]: scopedEntry }, scopedMessages);
  await writeLocalizationArtifacts(root);
  const generated = path.join(root, 'localization/generated');
  const scopedFile = path.join(generated, 'web-admin/bundles/en-US.json');
  await unlink(scopedFile);
  await assert.rejects(checkLocalizationArtifacts(root), /artifact is missing: localization\/generated\/web-admin\/bundles\/en-US.json/);
  await writeLocalizationArtifacts(root);
  await writeFile(scopedFile, '{}\n');
  await assert.rejects(checkLocalizationArtifacts(root), /artifact is stale: localization\/generated\/web-admin\/bundles\/en-US.json/);
  await writeLocalizationArtifacts(root);
  for (const group of ['', 'legacy', 'web-admin']) await writeFile(path.join(generated, group, 'bundles/fr.json'), '{}\n');
  await assert.rejects(checkLocalizationArtifacts(root), /artifact is stale/);
  await writeLocalizationArtifacts(root);
  for (const group of ['', 'legacy', 'web-admin']) await assert.rejects(stat(path.join(generated, group, 'bundles/fr.json')), { code: 'ENOENT' });
  await checkLocalizationArtifacts(root);

  await writeSources(root, runtimeCatalog, runtimeMessages);
  await assert.rejects(checkLocalizationArtifacts(root), /artifact is stale: localization\/generated\/web-admin/);
  await writeLocalizationArtifacts(root);
  await assert.rejects(stat(path.join(generated, 'web-admin/manifest.json')), { code: 'ENOENT' });
  await assert.rejects(stat(scopedFile), { code: 'ENOENT' });
  await checkLocalizationArtifacts(root);
});
